      }
    ],
    "lacunas": [
      "A ficha de precedências é referenciada, mas suas relações não estão disponíveis; não é possível determinar se a redução da duração do dossiê altera o término final."
    ],
    "motivo": "O aviso reduz em dois dias a duração do dossiê, mas o efeito sobre o marco final depende das precedências ausentes.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "Sem as relações de precedência, não se pode determinar se a atividade reduz o caminho que governa o término nem a magnitude da variação."
    ],
    "motivo": "A duração da atividade diminui, mas o aviso isolado não permite concluir a variação do término do projeto.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "Custo total declarado da linha base, corroborado pelas obrigações fixas e pelo apoio.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O custo recalculado do apoio depende do término novo, que não é determinável sem as precedências."
    ],
    "motivo": "O aditivo permite crédito da extensão não usada, mas seu valor depende do término final novo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A variação monetária depende da extensão não usada, calculada a partir do término novo, que é indeterminado."
    ],
    "motivo": "Não há custo direto pela digitalização; o efeito de custo decorre do crédito do apoio e não pode ser quantificado sem o término novo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base é declarada em D12 e 165000 centavos. O aviso encurta o dossiê e autoriza recalcular com crédito a extensão do apoio, mas as precedências necessárias para estabelecer o término novo não estão presentes. Não se presume seu efeito sobre o término nem sobre o custo."
}

